mapper.update:
UPDATE USER_EVENTS
SET COUNT = COUNT + #{count},
    UPDATED_AT = SYSDATE
WHERE ACCOUNT_ID = #{accountId}
  AND EVENT_TYPE = #{eventType}
  AND EVENT_NAME = #{eventName}

UPDATE USER_EVENTS
SET COUNT = GREATEST(COUNT - #{count}, 0),
    UPDATED_AT = SYSDATE
WHERE ACCOUNT_ID = #{accountId}
  AND EVENT_TYPE = #{eventType}
  AND EVENT_NAME = #{eventName}

mapper.select:
SELECT COUNT(*)
FROM USER_EVENTS
WHERE ACCOUNT_ID = #{accountId}

SELECT NVL(SUM(COUNT), 0)
FROM USER_EVENTS
WHERE ACCOUNT_ID = #{accountId}
  AND EVENT_TYPE = #{eventType}
